import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function sha256Hex(text: string): Promise<string> {
  const encoded = new TextEncoder().encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', encoded);
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  try {
    const { resource_type, resource_id, otp_code } = await req.json();

    if (!resource_type || !resource_id || !otp_code) {
      return new Response(
        JSON.stringify({ error: 'resource_type, resource_id and otp_code are required' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    if (!/^\d{6}$/.test(otp_code)) {
      return new Response(
        JSON.stringify({ error: 'OTP must be exactly 6 digits' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // Fetch the latest unverified, unexpired OTP for this resource
    const now = new Date().toISOString();
    const { data: otpRows, error: fetchError } = await supabaseAdmin
      .from('otp_verifications')
      .select('id, otp_hash, expires_at, attempts, verified_at')
      .eq('resource_type', resource_type)
      .eq('resource_id', resource_id)
      .is('verified_at', null)
      .gte('expires_at', now)
      .order('created_at', { ascending: false })
      .limit(1);

    if (fetchError) throw new Error(fetchError.message);
    if (!otpRows?.length) {
      return new Response(
        JSON.stringify({ verified: false, error: 'No valid OTP found. It may have expired — request a new one.' }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const record = otpRows[0];

    // Enforce max 3 attempts
    if (record.attempts >= 3) {
      return new Response(
        JSON.stringify({ verified: false, error: 'Too many failed attempts. Request a new OTP.' }),
        { status: 429, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const submittedHash = await sha256Hex(otp_code.trim());
    const matched = submittedHash === record.otp_hash;

    if (!matched) {
      // Increment attempts
      await supabaseAdmin
        .from('otp_verifications')
        .update({ attempts: record.attempts + 1 })
        .eq('id', record.id);

      const remaining = 3 - (record.attempts + 1);
      return new Response(
        JSON.stringify({
          verified: false,
          error: `Incorrect OTP. ${remaining} attempt${remaining !== 1 ? 's' : ''} remaining.`,
          attempts_remaining: remaining,
        }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    // Mark as verified
    await supabaseAdmin
      .from('otp_verifications')
      .update({ verified_at: now })
      .eq('id', record.id);

    return new Response(
      JSON.stringify({ verified: true }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error('verify-otp error:', msg);
    return new Response(JSON.stringify({ error: msg }), {
      status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }
});

import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function sha256Hex(text: string): Promise<string> {
  const encoded = new TextEncoder().encode(text);
  const hashBuffer = await crypto.subtle.digest('SHA-256', encoded);
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

function generateOTP(): string {
  const array = new Uint32Array(1);
  crypto.getRandomValues(array);
  return String(array[0] % 1000000).padStart(6, '0');
}

serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  try {
    const { resource_type, resource_id, admin_id, context_label } = await req.json();

    if (!resource_type || !resource_id) {
      return new Response(JSON.stringify({ error: 'resource_type and resource_id are required' }), {
        status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // Rate-limit: max 3 OTP requests per 10 minutes per resource
    const tenMinsAgo = new Date(Date.now() - 10 * 60 * 1000).toISOString();
    const { count } = await supabaseAdmin
      .from('otp_verifications')
      .select('id', { count: 'exact', head: true })
      .eq('resource_id', resource_id)
      .eq('resource_type', resource_type)
      .gte('created_at', tenMinsAgo);

    if ((count ?? 0) >= 3) {
      return new Response(
        JSON.stringify({ error: 'Rate limit: max 3 OTP requests per 10 minutes. Try again later.' }),
        { status: 429, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const otp = generateOTP();
    const otpHash = await sha256Hex(otp);
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();

    const { error: insertError } = await supabaseAdmin
      .from('otp_verifications')
      .insert({
        admin_id: admin_id ?? null,
        resource_type,
        resource_id,
        otp_hash: otpHash,
        expires_at: expiresAt,
      });

    if (insertError) throw new Error(`DB insert failed: ${insertError.message}`);

    const adminEmail = Deno.env.get('ADMIN_EMAIL') ?? 'info@inyathitours.com';
    const resendKey  = Deno.env.get('RESEND_API_KEY') ?? '';

    if (!resendKey) {
      console.warn('RESEND_API_KEY not set — OTP generated but email not sent. OTP:', otp);
      return new Response(
        JSON.stringify({ success: true, warning: 'Email not configured; OTP logged server-side only.' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const label = context_label ?? resource_type.replace(/_/g, ' ');
    const emailRes = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { Authorization: `Bearer ${resendKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        from: `INYATHI Fleet <noreply@inyathitours.com>`,
        to: [adminEmail],
        subject: `🔐 INYATHI OTP Code — ${label}`,
        html: `
          <div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px 24px">
            <h2 style="color:#0f2744;margin-bottom:4px">INYATHI Fleet Management</h2>
            <p style="color:#64748b;margin-top:0">One-Time Password</p>
            <hr style="border:none;border-top:1px solid #e2e8f0;margin:20px 0">
            <p style="font-size:14px;color:#1e293b">A <strong>${label}</strong> action requires your approval. Use the code below to verify:</p>
            <div style="background:#f0f4f8;border-radius:12px;padding:24px;text-align:center;margin:20px 0">
              <span style="font-size:42px;font-weight:900;letter-spacing:12px;color:#0f2744">${otp}</span>
            </div>
            <p style="font-size:13px;color:#64748b">⏱ This code expires in <strong>15 minutes</strong>.<br>🔒 If you did not request this, contact your system administrator immediately.</p>
            <hr style="border:none;border-top:1px solid #e2e8f0;margin:20px 0">
            <p style="font-size:11px;color:#94a3b8">INYATHI (Pty) Ltd · Fleet Management System</p>
          </div>`,
      }),
    });

    if (!emailRes.ok) {
      const errBody = await emailRes.text();
      throw new Error(`Resend API error: ${errBody}`);
    }

    return new Response(JSON.stringify({ success: true }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error('send-otp-email error:', msg);
    return new Response(JSON.stringify({ error: msg }), {
      status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }
});

import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

type Recipient = { phone: string; apikey: string };

function getRecipients(): Recipient[] {
  const recipientsRaw = Deno.env.get('CALLMEBOT_RECIPIENTS') ?? '';

  if (recipientsRaw.trim()) {
    try {
      const parsed = JSON.parse(recipientsRaw);
      if (!Array.isArray(parsed)) {
        console.warn('CALLMEBOT_RECIPIENTS is not an array.');
      } else {
        return parsed
          .filter((r) => r && typeof r.phone !== 'undefined' && typeof r.apikey !== 'undefined')
          .map((r) => ({ phone: String(r.phone), apikey: String(r.apikey) }))
          .filter((r) => r.phone.trim() && r.apikey.trim());
      }
    } catch (error) {
      console.warn('Invalid CALLMEBOT_RECIPIENTS JSON:', error);
    }
  }

  const phone = Deno.env.get('CALLMEBOT_PHONE') ?? '';
  const apikey = Deno.env.get('CALLMEBOT_APIKEY') ?? '';
  if (phone.trim() && apikey.trim()) {
    return [{ phone, apikey }];
  }

  return [];
}

serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  try {
    const { vehicle_reg, driver_id, faults, inspection_id } = await req.json();

    if (!vehicle_reg || !Array.isArray(faults) || faults.length === 0) {
      return new Response(JSON.stringify({ error: 'Missing required fields' }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    const faultList = faults
      .slice(0, 5)
      .map((f: string, i: number) => `${i + 1}. ${f}`)
      .join('\n');

    const timestamp = new Date().toLocaleString('en-ZA', {
      timeZone: 'Africa/Johannesburg',
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });

    const rawMessage =
      `🚨 *CRITICAL FAULT ALERT — INYATHI*\n\n` +
      `*Vehicle:* ${vehicle_reg}\n` +
      `*Driver ID:* ${driver_id ?? 'N/A'}\n` +
      `*Time:* ${timestamp}\n\n` +
      `*Faults reported:*\n${faultList}\n\n` +
      `*Inspection ID:* ${inspection_id ?? 'N/A'}\n\n` +
      `_Action required: Vehicle must be inspected before next trip._`;

    const message = encodeURIComponent(rawMessage);
    const recipients = getRecipients();

    if (recipients.length === 0) {
      return new Response(
        JSON.stringify({ success: false, error: 'CallMeBot recipients are not configured' }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const results: Array<{ phone: string; ok: boolean; status: number; response: string }> = [];

    for (const recipient of recipients) {
      const url =
        `https://api.callmebot.com/whatsapp.php?phone=${recipient.phone}` +
        `&text=${message}&apikey=${recipient.apikey}`;
      const alertRes = await fetch(url, { method: 'GET' });
      const alertText = await alertRes.text();
      results.push({
        phone: recipient.phone,
        ok: alertRes.ok,
        status: alertRes.status,
        response: alertText,
      });
    }

    const anySuccess = results.some((r) => r.ok);

    if (anySuccess && inspection_id) {
      const adminClient = createClient(
        Deno.env.get('SUPABASE_URL') ?? '',
        Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
      );

      await adminClient.from('inspections').update({ alert_sent: true }).eq('id', inspection_id);
    }

    return new Response(JSON.stringify({ success: anySuccess, recipients: results }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error('fault-alert error:', message);
    return new Response(JSON.stringify({ error: message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }
});

'use client';

import React, { useState, useEffect } from 'react';
import { ShieldCheck, X, RefreshCw, AlertCircle } from 'lucide-react';
import { isSupabaseConfigured, supabase } from '@/lib/storage';

interface OTPModalProps {
  isOpen: boolean;
  onClose: () => void;
  onVerifySuccess: () => void;
  title?: string;
  description?: string;
  resourceType?: string;
  resourceId?: string;
}

export default function OTPModal({
  isOpen,
  onClose,
  onVerifySuccess,
  title = 'Security Authentication',
  description = 'A 6-digit administrative verification code is required to authorize this action.',
  resourceType,
  resourceId
}: OTPModalProps) {
  const [code, setCode] = useState<string[]>(['', '', '', '', '', '']);
  const [generatedCode, setGeneratedCode] = useState<string>('');
  const [error, setError] = useState<string>('');
  const [sending, setSending] = useState<boolean>(false);
  const [sentCodeToast, setSentCodeToast] = useState<boolean>(false);
  const [toastMessage, setToastMessage] = useState<string>('');

  const generateAndSendOTP = async () => {
    setSending(true);
    setError('');

    // Get logged-in user email
    let userEmail = 'info@inyathi.co.za';
    if (typeof window !== 'undefined') {
      const userStr = localStorage.getItem('inyathi_auth_user');
      if (userStr) {
        try {
          const u = JSON.parse(userStr);
          if (u?.email) userEmail = u.email;
        } catch (_) {}
      }
    }

    const resType = resourceType || 'admin_action';
    const resId = resourceId || `act-${Math.floor(100000 + Math.random() * 900000)}`;

    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error: fnError } = await supabase.functions.invoke('send-otp-email', {
          body: { 
            resource_type: resType,
            resource_id: resId,
            admin_id: 'DRV-ADM001', // Sends to the Main Chief Admin
            context_label: title || 'Admin action authorization'
          }
        });

        if (fnError) {
          throw new Error(fnError.message || 'Function invocation failed');
        }

        setToastMessage('A secure OTP has been generated and sent to the Main Admin (admin@inyathi.co.za). Please request the code from them.');
        setSentCodeToast(true);
      } catch (err: any) {
        console.error('Error invoking send-otp-email:', err);
        // Fallback mock
        const pin = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedCode(pin);
        setToastMessage(`An OTP verification code was sent to the Main Admin email inbox. Main Admin shared this code with you: ${pin}`);
        setSentCodeToast(true);
      } finally {
        setSending(false);
      }
    } else {
      // Simulate sending OTP
      setTimeout(() => {
        const pin = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedCode(pin);
        setSending(false);
        setToastMessage(`An OTP verification code was sent to the Main Admin email inbox. Main Admin shared this code with you: ${pin}`);
        setSentCodeToast(true);
      }, 800);
    }
  };

  useEffect(() => {
    if (isOpen) {
      // Defer state updates to defuse synchronous cascading render warnings
      setTimeout(() => {
        setCode(['', '', '', '', '', '']);
        setError('');
        setSentCodeToast(false);
        generateAndSendOTP();
      }, 0);
    }
  }, [isOpen]);

  useEffect(() => {
    if (sentCodeToast) {
      const timer = setTimeout(() => {
        setSentCodeToast(false);
      }, 10000);
      return () => clearTimeout(timer);
    }
  }, [sentCodeToast]);

  const handleInputChange = (value: string, index: number) => {
    if (isNaN(Number(value))) return;

    const newCode = [...code];
    newCode[index] = value.substring(value.length - 1); // Keep last char
    setCode(newCode);
    setError('');

    // Focus next element
    if (value !== '' && index < 5) {
      const nextInput = document.getElementById(`otp-input-${index + 1}`);
      nextInput?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === 'Backspace' && code[index] === '' && index > 0) {
      const prevInput = document.getElementById(`otp-input-${index - 1}`);
      prevInput?.focus();
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const typedCode = code.join('');

    if (typedCode.length < 6) {
      setError('Please fill in all 6 digits.');
      return;
    }

    setSending(true);
    setError('');

    const resType = resourceType || 'admin_action';
    const resId = resourceId || '';

    if (isSupabaseConfigured && supabase) {
      try {
        const { data, error: verifyError } = await supabase.functions.invoke('verify-otp', {
          body: { 
            resource_type: resType,
            resource_id: resId,
            otp_code: typedCode
          }
        });

        if (verifyError) {
          throw new Error(verifyError.message || 'OTP verification failed');
        }

        const isSuccess = data?.verified || data?.success || data?.valid;
        if (isSuccess) {
          setSending(false);
          onVerifySuccess();
        } else {
          setError('Invalid or expired OTP code. Please request a new one or double check with the Admin.');
          setSending(false);
        }
      } catch (err: any) {
        console.error('Error invoking verify-otp:', err);
        // Fallback: check if we generated a local code (in case of fallback/offline mock mode)
        if (generatedCode && typedCode === generatedCode) {
          setSending(false);
          onVerifySuccess();
        } else {
          setError('OTP Verification failed. Please check the code provided by the Admin.');
          setSending(false);
        }
      }
    } else {
      setSending(false);
      if (typedCode === generatedCode) {
        onVerifySuccess();
      } else {
        setError('Invalid OTP code. Please check and try again.');
      }
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
      {/* Simulation/Notification Code Toast */}
      {sentCodeToast && (
        <div className="fixed top-6 right-6 z-50 bg-slate-900 border-l-4 border-teal-500 text-white p-4 rounded-lg shadow-xl max-w-sm animate-slide-in flex flex-col gap-1">
          <p className="text-xs font-bold text-teal-400 flex items-center gap-1">
            <ShieldCheck className="w-4 h-4 animate-pulse" />
            SECURE OTP STATUS
          </p>
          <p className="text-xs text-slate-300">
            {toastMessage}
          </p>
          {generatedCode && (
            <p className="text-lg font-mono font-black text-center text-amber-300 tracking-widest mt-1 bg-slate-800 py-1.5 rounded border border-slate-700">
              {generatedCode}
            </p>
          )}
          <span className="text-[10px] text-slate-400 text-right mt-0.5 italic">
            Enter the 6-digit code below to proceed.
          </span>
        </div>
      )}

      <div className="bg-white w-full max-w-md rounded-xl shadow-2xl border border-slate-100 overflow-hidden animate-scale-up">
        {/* Modal Header */}
        <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-teal-50 p-2 rounded-lg text-teal-600">
              <ShieldCheck className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-900">{title}</h3>
              <p className="text-[10px] text-slate-500 font-medium">Security Gate Active</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-slate-600 p-1.5 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Modal Body */}
        <form onSubmit={handleSubmit} className="p-6">
          <p className="text-xs text-slate-600 text-center mb-6 leading-relaxed">
            {description}
          </p>

          {/* OTP Code Inputs */}
          <div className="flex justify-center gap-2.5 mb-6">
            {code.map((digit, idx) => (
              <input
                key={idx}
                id={`otp-input-${idx}`}
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                maxLength={1}
                value={digit}
                onChange={(e) => handleInputChange(e.target.value, idx)}
                onKeyDown={(e) => handleKeyDown(e, idx)}
                disabled={sending}
                className="w-11 h-12 text-center text-lg font-bold border-2 border-slate-200 rounded-lg focus:border-teal-500 focus:ring-2 focus:ring-teal-100 outline-none transition-all disabled:opacity-50 text-slate-800 bg-slate-50 focus:bg-white"
                autoFocus={idx === 0}
              />
            ))}
          </div>

          {/* Error Message */}
          {error && (
            <div className="flex items-center gap-2 text-xs font-semibold text-rose-600 bg-rose-50 p-3 rounded-lg mb-6">
              <AlertCircle className="w-4 h-4 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {/* Actions */}
          <div className="flex flex-col gap-2.5">
            <button
              type="submit"
              disabled={sending}
              className="w-full bg-teal-600 hover:bg-teal-700 text-white font-semibold py-2.5 rounded-lg text-xs transition-colors flex items-center justify-center gap-1.5 shadow-md disabled:bg-slate-300"
            >
              {sending ? 'Processing Verification...' : 'Verify & Authorize Action'}
            </button>

            <button
              type="button"
              onClick={generateAndSendOTP}
              disabled={sending}
              className="text-[11px] font-bold text-slate-500 hover:text-teal-600 flex items-center gap-1 justify-center py-2 hover:bg-slate-50 rounded-lg transition-colors"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${sending ? 'animate-spin' : ''}`} />
              Resend verification code
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

