```ts
saveFine: async (fine: TrafficFine): Promise<TrafficFine> => {
    const list = getLocalStorageItem<TrafficFine[]>(STORAGE_KEYS.FINES, []);
    const idx = list.findIndex(f => f.id === fine.id);
    const now = new Date().toISOString();

    const prepared = {
      ...fine,
      updated_at: now
    };

    if (idx !== -1) {
      list[idx] = prepared;
