        from: Deno.env.get('FINE_EMAIL_FROM') ?? 'INYATHI Fleet <noreply@inyathi.co.za>',
        to: recipients,
        subject,
        html,
      }),
    });

    if (!emailRes.ok) {
      const errorText = await emailRes.text();
      await supabaseAdmin
        .from('traffic_fines')
        .update({ notification_error: `Resend error: ${errorText}` })
        .eq('id', traffic_fine_id);
