      return jsonResponse({ error: 'Admin access required' }, 403);
    }

    const { data: fine, error: fineError } = await supabaseAdmin
      .from('traffic_fines')
      .select(`
        id,
        booking_id,
        vehicle_reg,
        driver_id,
        fine_timestamp,
        fine_reference,
        location,
        description,
        amount,
